def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in into s_out."""
    # Simple approach: find first differing character
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found first difference
            if len(s_in) < len(s_out):
                # Insertion case
                return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion case  
                return (s_in[i], "", i)
            else:
                # Substitution case
                return (s_in[i], s_out[i], i)

    # If we've reached here, one string is prefix of other
    if len(s_in) < len(s_out):
        return (s_in[-1] if s_in else "", s_out[len(s_in)], len(s_in))
    elif len(s_in) > len(s_out):
        return (s_in[len(s_out)], "", len(s_out))
    else:
        return ("", "", -1)  # No difference

